import{_ as e,c as l,aU as s,a as d}from"./chunks/framework.DIXiA2XH.js";const y=JSON.parse('{"title":"k8s","description":"","frontmatter":{},"headers":[],"relativePath":"note/server/docker/k8s.md","filePath":"note/server/docker/k8s.md","lastUpdated":1785334184000}'),n={name:"note/server/docker/k8s.md"};function r(a,t,g,o,i,f){return d(),l("div",null,[...t[0]||(t[0]=[s('<h1 id="k8s" tabindex="-1">k8s <a class="header-anchor" href="#k8s" aria-label="Permalink to &quot;k8s&quot;">​</a></h1><p><a href="https://www.yuque.com/xiaoguai-pbjfj/cxxcrs/ocefqltbmbgl5eqg?singleDoc#" target="_blank" rel="noreferrer">https://www.yuque.com/xiaoguai-pbjfj/cxxcrs/ocefqltbmbgl5eqg?singleDoc#</a></p><p><a href="https://www.yuque.com/atguigu-team/frzi7z?#" target="_blank" rel="noreferrer">https://www.yuque.com/atguigu-team/frzi7z?#</a> 《k8s专区》 密码：trk3</p><table tabindex="0"><thead><tr><th style="text-align:left;">对比维度</th><th style="text-align:left;"><strong>Kind</strong></th><th style="text-align:left;"><strong>Kubeadm</strong></th><th style="text-align:left;"><strong>Rancher</strong></th><th style="text-align:left;"><strong>KubeSphere</strong></th></tr></thead><tbody><tr><td style="text-align:left;"><strong>是什么</strong></td><td style="text-align:left;">一个用 Docker 容器模拟 K8s 节点的工具</td><td style="text-align:left;">K8s 官方的集群生命周期管理工具</td><td style="text-align:left;">企业级容器管理平台</td><td style="text-align:left;"><strong>全栈式云原生应用平台</strong></td></tr><tr><td style="text-align:left;"><strong>主要用途</strong></td><td style="text-align:left;">本地开发 / 测试 / CI</td><td style="text-align:left;">搭建生产级 K8s 集群</td><td style="text-align:left;">统一管理多套 K8s 集群</td><td style="text-align:left;"><strong>提供开发、部署、运维一体化能力</strong></td></tr><tr><td style="text-align:left;"><strong>使用场景</strong></td><td style="text-align:left;">在自己电脑上写代码、学习 K8s、跑自动化测试</td><td style="text-align:left;">有一批服务器，要正式搭建一个 K8s 集群</td><td style="text-align:left;">公司有多个 K8s 集群（测试/生产/不同云厂商）需要统一管</td><td style="text-align:left;"><strong>需要一站式解决监控、日志、DevOps、微服务治理的团队</strong></td></tr><tr><td style="text-align:left;"><strong>运行依赖</strong></td><td style="text-align:left;">需要 Docker</td><td style="text-align:left;">需要 Linux 服务器（物理机/虚拟机）</td><td style="text-align:left;">需要一台或多台服务器部署它自己</td><td style="text-align:left;">需要一台或多台服务器部署它自己（可部署在 K8s 上）</td></tr><tr><td style="text-align:left;"><strong>有图形界面吗</strong></td><td style="text-align:left;">❌ 无</td><td style="text-align:left;">❌ 无</td><td style="text-align:left;">✅ 有（Web UI）<br><em>专注集群管理</em></td><td style="text-align:left;">✅ 有（Web UI）<br><em>功能更丰富，侧重“应用”</em></td></tr><tr><td style="text-align:left;"><strong>生产环境可用吗</strong></td><td style="text-align:left;">❌ 不行（性能/稳定性不适合）</td><td style="text-align:left;">✅ 可以（官方推荐的生产部署方式）</td><td style="text-align:left;">✅ 可以（用来管理生产集群）</td><td style="text-align:left;">✅ 可以（作为生产级 PaaS 平台使用）</td></tr><tr><td style="text-align:left;"><strong>学习曲线</strong></td><td style="text-align:left;">很平缓</td><td style="text-align:left;">较陡峭</td><td style="text-align:left;">中等</td><td style="text-align:left;">中等（概念较多，但向导清晰）</td></tr><tr><td style="text-align:left;"><strong>典型命令/操作</strong></td><td style="text-align:left;"><code>kind create cluster</code></td><td style="text-align:left;"><code>kubeadm init</code> / <code>kubeadm join</code></td><td style="text-align:left;">网页上点按钮 / <code>rancher-cli</code></td><td style="text-align:left;">网页上创建 DevOps 流水线 / 点击部署应用</td></tr><tr><td style="text-align:left;"><strong>核心特点</strong></td><td style="text-align:left;">极简、快速、用完即焚</td><td style="text-align:left;">官方标准、安全、可扩展</td><td style="text-align:left;"><strong>多集群管理能力极强</strong>、支持集群导入</td><td style="text-align:left;"><strong>功能全集成（DevOps/观察/微服务）</strong>、对开发者友好</td></tr><tr><td style="text-align:left;"><strong>维护方</strong></td><td style="text-align:left;">Kubernetes SIGs</td><td style="text-align:left;">Kubernetes 官方</td><td style="text-align:left;">Rancher Labs (SUSE)</td><td style="text-align:left;">青云科技 (QingCloud) + 开源社区</td></tr><tr><td style="text-align:left;"><strong>🏠 生活比喻</strong></td><td style="text-align:left;"><strong>乐高玩具样板间</strong><br>在自己桌上快速拼一个小模型，体验一下房子长啥样，拆了也不心疼。</td><td style="text-align:left;"><strong>标准施工队+建材包</strong><br>给你一套正规图纸和水泥钢筋，让你按标准流程自己盖一栋能住人的毛坯房。</td><td style="text-align:left;"><strong>专业物业管理公司</strong><br>你手里有好几栋楼（可能在不同城市），它能帮你统一管起来，收租、安保、维修调度。</td><td style="text-align:left;"><strong>全屋智能精装服务商</strong><br>不仅给你房子，还把全屋智能家电、水电网络、装修都按最佳实践装好，拎包就能入住办公。</td></tr></tbody></table><hr><p>Kubeadm 只负责搭建，搭完就是纯命令行的。当然可以自己额外加装 Kubernetes Dashboard（官方 Web UI）</p><p>但这个 Dashboard 和 Rancher 不一样：</p><ul><li>只管理单个集群（不是管理多集群的统一平台）</li><li>功能弱很多（没有多租户管理、不集成监控/日志）</li><li>要自己额外配置访问权限和认证</li></ul><p>如果你要很多的集群。那就要用到 Rancher了</p><hr>',10)])])}const c=e(n,[["render",r]]);export{y as __pageData,c as default};
